export function componentPortSnap(x:number,y:number,width:number,height:number){const h=8,cx=x+h,cy=y+h;const choices=[{side:'left',d:Math.abs(cx),x:-h,y:Math.max(-h,Math.min(height-h,y))},{side:'right',d:Math.abs(cx-width),x:width-h,y:Math.max(-h,Math.min(height-h,y))},{side:'top',d:Math.abs(cy),x:Math.max(-h,Math.min(width-h,x)),y:-h},{side:'bottom',d:Math.abs(cy-height),x:Math.max(-h,Math.min(width-h,x)),y:height-h}];const best=choices.sort((a,b)=>a.d-b.d)[0];return {x:Math.round(best.x),y:Math.round(best.y)}}
