   const detail=e.uml?.component;if(detail?.kind==='port'&&detail.typeId){const a=new Set<string>(),b=new Set<string>();resolve(detail.typeId,a,b,new Set(visited),false);for(const x of detail.isConjugated?b:a)p.add(x);for(const x of detail.isConjugated?a:b)r.add(x)}else incomplete=true
